class stringx
{
  char *chars;
  void *my_buf;

public:
  stringx(const stringx &);
  stringx(const char *, int len = -1);
  explicit stringx(int);
  ~stringx();
  stringx &operator=(const stringx &);
};

stringx operator+(const stringx &, const stringx &);

class SplitClockWidget
{
public:
  stringx GetTimeText(const int min, const float sec) const;
};

stringx SplitClockWidget::GetTimeText(const int min, const float sec) const
{
	stringx	clockText((int)sec);

	if (sec < 10)
		clockText = stringx("0") + clockText;
	clockText = stringx(min) + stringx(":") + clockText;

	return clockText;
}
